(()=>{
 'use strict';
 const $=id=>document.getElementById(id),canvas=$('plant-canvas'),ctx=canvas.getContext('2d'),back=document.createElement('canvas'),bg=back.getContext('2d'),mesh=buildPlantGeometry();
 const state={selected:'seaChest',filter:'all',step:0,running:false,speed:1,yaw:-.16,pitch:.22,zoom:1,labels:true,interior:true,time:0,target:[-.8,.9,0],panX:0,panY:0,panMode:false};
 let W=0,H=0,dpr=1,dirty=true,hits=[],surfaces=[],frame=0,last=0,lastPaint=0,drag=null,alive=true;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const groups={sea:'AGUA DE MAR',exchange:'INTERCAMBIO SIN MEZCLA',cycle:'AGUA Y VAPOR',makeup:'REPOSICIÓN',heat:'APORTE DE CALOR'};
 function project(p){const [x,y,depth]=plantCameraPoint(p,state.target,state.yaw,state.pitch),scale=Math.min((W-70)/19.8,(H-85)/11)*state.zoom;return[W/2+x*scale+state.panX,H*.49-y*scale+state.panY,depth]}
 function resetCamera(){state.yaw=-.16;state.pitch=.22;state.zoom=1;state.target=[-.8,.9,0];state.panX=state.panY=0;dirty=true;canvas.dataset.focusedPart='';}
 function focusPart(id){const r=canvas.getBoundingClientRect(),camera=plantFocusCamera(mesh,id,state.yaw,state.pitch,r.width,r.height);if(!camera)return;select(id);Object.assign(state,camera,{panX:0,panY:0});if(['upper','separator'].includes(id)){state.interior=true;$('interior').setAttribute('aria-pressed','true')}canvas.dataset.focusedPart=id;dirty=true;canvas.scrollIntoView({block:'nearest',behavior:'auto'});}

 function shade(hex,n){return '#'+hex.slice(1).match(/../g).map(v=>Math.min(255,Math.max(0,Math.round(parseInt(v,16)*n))).toString(16).padStart(2,'0')).join('')}
 function chosen(id){const n=plantNodes[id];return state.filter==='all'||state.filter==='sea'?(state.filter==='all'||n.group==='sea'||id==='condenser'):state.filter==='makeup'?['makeup','feedTank','feedPump'].includes(id):['cycle','exchange','heat'].includes(n.group)}
 function list(){const q=$('part-search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();$('part-list').innerHTML=Object.entries(groups).map(([g,title])=>{const nodes=Object.values(plantNodes).filter(n=>n.group===g&&chosen(n.id)&&`${n.name} ${n.fluid}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));return nodes.length?`<h3>${title}</h3>${nodes.map(n=>`<button data-part="${n.id}" aria-pressed="${state.selected===n.id}"><b>${n.number}</b><span>${esc(n.name)}</span></button>`).join('')}`:''}).join('')||'<p>Sin coincidencias.</p>';for(const b of $('part-list').querySelectorAll('button')){b.onclick=()=>select(b.dataset.part);b.ondblclick=()=>focusPart(b.dataset.part);b.title='Doble clic para enfocar en 3D';}}
 function detail(){const n=plantNodes[state.selected],tour=plantTours[state.filter],connected=plantEdges.filter(e=>plantRelated(e,n.id));$('part-detail').innerHTML=`<span class="fluid-badge">${n.number} · ${esc(n.fluid)}</span><h2>${esc(n.name)}</h2><p>${esc(n.description)}</p><h3>Conexiones</h3>${connected.map(e=>`<p class="connection">${esc(plantNodes[e.from].name)} → ${esc(plantNodes[e.to].name)}${e.recirculation?' · agua que recircula':''}${e.aux?' · ramal auxiliar':''}</p>`).join('')}<p class="caution">${esc(n.note)}</p>`;$('step-count').textContent=`${state.step+1} / ${tour.length}`;$('previous').disabled=state.step===0;$('next').disabled=state.step===tour.length-1;for(const b of $('part-list').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.part===n.id));}
 function select(id,step){if(!plantNodes[id])return;state.selected=id;state.step=step??Math.max(0,plantTours[state.filter].indexOf(id));dirty=true;detail()}
 function polygon(c,points){c.beginPath();points.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath()}
 function line(c,points,color,width,dash=[]){c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash);c.beginPath();points.map(project).forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();c.setLineDash([])}
 function base(){
  bg.setTransform(dpr,0,0,dpr,0,0);bg.clearRect(0,0,W,H);bg.fillStyle='#eff3ef';bg.fillRect(0,0,W,H);
  for(let i=-10;i<=9;i++)line(bg,[[i,-3.75,-3],[i,-3.75,4]],'#dce5dc',.6);for(let i=-3;i<=4;i++)line(bg,[[-10,-3.75,i],[9,-3.75,i]],'#dce5dc',.6);
  surfaces=mesh.faces.filter(f=>state.interior||!f.internal).map(f=>({...f,p:f.v.map(project)})).map(f=>({...f,depth:f.p.reduce((s,p)=>s+p[2],0)/f.p.length})).sort((a,b)=>b.depth-a.depth);
  for(const f of surfaces){const active=f.id===state.selected,muted=!chosen(f.id),a=f.v[1].map((v,i)=>v-f.v[0][i]),b=f.v[2].map((v,i)=>v-f.v[0][i]),n=[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],len=Math.hypot(...n)||1,light=f.shade||(.7+.22*Math.abs((n[0]*.4+n[1]*.8+n[2]*.2)/len));polygon(bg,f.p);bg.globalAlpha=muted?.12:f.drum&&state.interior?.16:f.alpha;bg.fillStyle=shade(f.color,light+(active?.12:0));bg.fill();bg.globalAlpha=muted?.06:f.alpha*.45;bg.strokeStyle=active?'#123d3b':shade(f.color,.65);bg.lineWidth=active?.55:.22;bg.stroke()}
  bg.globalAlpha=1;line(bg,mesh.attemperatorLeader,'#93789a',1.2,[3,4]);
  // Explicit tube/shell annotation is fixed to separate ports, not a fluid connection.
  if(state.selected==='condenser'){const a=project([-7,.35,0]);bg.font='bold 11px system-ui';bg.fillStyle='#146b99';bg.fillText('MAR · dentro de los tubos',Math.max(10,a[0]-90),a[1]+45);bg.fillStyle='#884e70';bg.fillText('VAPOR · fuera de los tubos',Math.max(10,a[0]-90),a[1]-48)}
  if(state.selected==='attemperator'){const a=project(P('attemperator'));bg.font='11px system-ui';bg.fillStyle='#755784';bg.fillText('Detalle ampliado · en zona de agua del domo',Math.max(8,Math.min(W-275,a[0]-180)),a[1]-28)}
  hits=[];if(state.labels){const used=[];for(const n of Object.values(plantNodes).filter(n=>chosen(n.id))){const a=project(mesh.anchors[n.id]);if(a[0]<-12||a[0]>W+12||a[1]<-12||a[1]>H+12)continue;const offsets=[[0,-18],[22,0],[-22,0],[0,24],[24,-24],[-24,-24],[40,18],[-40,18],[0,-50],[50,-40],[-50,-40],[65,0],[-65,0],[0,65]];let c=null;for(const [dx,dy]of offsets){const p=[Math.min(W-16,Math.max(16,a[0]+dx)),Math.min(H-38,Math.max(18,a[1]+dy))];if(!used.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<28)){c=p;break}}if(!c)c=[Math.min(W-16,Math.max(16,a[0])),Math.min(H-38,Math.max(18,a[1]-75))];used.push(c);bg.strokeStyle=n.id===state.selected?'#284f48':'#859a91';bg.lineWidth=.7;bg.beginPath();bg.moveTo(a[0],a[1]);bg.lineTo(c[0],c[1]);bg.stroke();bg.beginPath();bg.arc(c[0],c[1],11,0,Math.PI*2);bg.fillStyle=n.id===state.selected?'#194d46':'#ffffff';bg.fill();bg.stroke();bg.font='bold 10px system-ui';bg.textAlign='center';bg.textBaseline='middle';bg.fillStyle=n.id===state.selected?'white':'#315d55';bg.fillText(n.number,c[0],c[1]);hits.push({id:n.id,x:c[0],y:c[1]})}bg.textAlign='left';bg.textBaseline='alphabetic'}
  dirty=false;
 }
 function draw(time){if(!alive)return;frame=requestAnimationFrame(draw);const dt=last?Math.min(time-last,80):0;last=time;if(state.running&&!document.hidden)state.time+=dt*state.speed;if(time-lastPaint<32)return;lastPaint=time;const r=canvas.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,2);if(r.width!==W||r.height!==H||ratio!==dpr){W=r.width;H=r.height;dpr=ratio;canvas.width=back.width=Math.round(W*dpr);canvas.height=back.height=Math.round(H*dpr);dirty=true}if(!W||!H)return;if(dirty)base();ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.drawImage(back,0,0,W,H);
  const paths=[...plantEdges.filter(e=>plantEdgeVisible(e,state.filter)).map(e=>({...e,hot:plantRelated(e,state.selected)})),...mesh.paths.filter(p=>p.kind==='heat'?state.selected==='furnace':state.filter==='all'||state.filter==='sea'&&p.kind==='sea'||state.filter==='cycle'&&p.kind!=='sea').map(p=>({...p,hot:p.id===state.selected}))];
  for(const p of paths){const color=plantColors[p.kind];ctx.globalAlpha=p.hot?1:.55;line(ctx,p.points,color,p.hot?2:1,p.aux?[3,5]:[]);for(let i=0;i<3;i++){const t=(state.time/7000+i/3)%1,a=project(plantSample(p.points,t)),b=project(plantSample(p.points,Math.min(.999999,t+.008))),angle=Math.atan2(b[1]-a[1],b[0]-a[0]);ctx.save();ctx.translate(a[0],a[1]);ctx.rotate(angle);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(p.hot?6:4,0);ctx.lineTo(-3,-3);ctx.lineTo(-3,3);ctx.closePath();ctx.fill();ctx.restore()}}
  ctx.globalAlpha=1;
 }
 function setPlaying(v){state.running=v;$('play').textContent=v?'Ⅱ Pausar':'▶ Animar';$('play').setAttribute('aria-pressed',String(v))}
 $('play').onclick=()=>setPlaying(!state.running);$('speed').onchange=e=>state.speed=Number(e.target.value);$('circuit').onchange=e=>{state.filter=e.target.value;resetCamera();select(plantTours[state.filter][0],0);list()};$('previous').onclick=()=>{if(state.step>0)select(plantTours[state.filter][state.step-1],state.step-1)};$('next').onclick=()=>{if(state.step<plantTours[state.filter].length-1)select(plantTours[state.filter][state.step+1],state.step+1)};
 $('part-search').oninput=list;$('reset').onclick=resetCamera;$('front').onclick=()=>{state.yaw=0;state.pitch=0;dirty=true};const zoom=d=>{state.zoom=Math.max(.6,Math.min(14,state.zoom+d));dirty=true};$('zoom-in').onclick=()=>zoom(state.zoom*.18);$('zoom-out').onclick=()=>zoom(-state.zoom*.18);
 $('focus').onclick=()=>focusPart(state.selected);$('pan').onclick=()=>{state.panMode=!state.panMode;$('pan').setAttribute('aria-pressed',String(state.panMode));canvas.style.cursor=state.panMode?'move':'grab';};
 for(const [id,key]of [['labels','labels'],['interior','interior']])$(id).onclick=()=>{state[key]=!state[key];$(id).setAttribute('aria-pressed',String(state[key]));dirty=true};
 canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),x=e.clientX-r.left-W/2,y=e.clientY-r.top-H*.49,old=state.zoom;zoom(state.zoom*(e.deltaY<0?.12:-.12));const ratio=state.zoom/old;state.panX=x-(x-state.panX)*ratio;state.panY=y-(y-state.panY)*ratio;},{passive:false});
 canvas.addEventListener('keydown',e=>{const key=e.key;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-',' ','Enter','Escape'].includes(key))return;e.preventDefault();if(key==='Enter')focusPart(state.selected);else if(key==='Escape')resetCamera();else if(key===' ')setPlaying(!state.running);else if(key==='+'||key==='=')zoom(state.zoom*.18);else if(key==='-')zoom(-state.zoom*.18);else if(e.shiftKey||state.panMode){state.panX+=key==='ArrowLeft'?-32:key==='ArrowRight'?32:0;state.panY+=key==='ArrowUp'?-32:key==='ArrowDown'?32:0;dirty=true}else{state.yaw+=key==='ArrowLeft'?-.1:key==='ArrowRight'?.1:0;state.pitch=Math.max(-.65,Math.min(.8,state.pitch+(key==='ArrowUp'?.08:key==='ArrowDown'?-.08:0)));dirty=true}});
 canvas.addEventListener('contextmenu',e=>e.preventDefault());
 canvas.addEventListener('pointerdown',e=>{if(![0,1,2].includes(e.button))return;drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,pan:state.panMode||e.shiftKey||e.button!==0,button:e.button};canvas.setPointerCapture(e.pointerId)});
 canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.pan){state.panX+=dx;state.panY+=dy}else{state.yaw+=dx*.006;state.pitch=Math.max(-.65,Math.min(.8,state.pitch+dy*.006))}drag.x=e.clientX;drag.y=e.clientY;dirty=true});
 function inside(x,y,ps){let ok=false;for(let i=0,j=ps.length-1;i<ps.length;j=i++){const a=ps[i],b=ps[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])ok=!ok}return ok}
 function pickAt(e){const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,hit=hits.find(h=>Math.hypot(h.x-x,h.y-y)<15);if(hit)return hit.id;for(let i=surfaces.length-1;i>=0;i--){const f=surfaces[i];if(!f.connection&&chosen(f.id)&&inside(x,y,f.p))return f.id}return null;}
 canvas.addEventListener('pointerup',e=>{if(!drag)return;const moved=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY),button=drag.button;drag=null;if(moved>5||button!==0)return;const id=pickAt(e);if(id)select(id)});
 canvas.addEventListener('dblclick',e=>{e.preventDefault();const id=pickAt(e);if(id)focusPart(id)});
 canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('lostpointercapture',()=>drag=null);
 window.addEventListener('pagehide',()=>{alive=false;cancelAnimationFrame(frame)});window.addEventListener('pageshow',()=>{if(!alive){alive=true;last=0;dirty=true;frame=requestAnimationFrame(draw)}});
 detail();list();frame=requestAnimationFrame(draw);
})();
